INSERT [PnS].[Schema_MRDFRequest] ([Id], [FieldName], [Type], [StartPosition], [Length], [IsActive], [Description], [Comments], [SampleValue], [DataType], [DataFormatTemplate], [DefaultValue]) VALUES (25, N'InputWeight', N'ASCII_Alpha', 25, 5, 1, N'This field mus t conta in a va lue. Eithe r enter 0.000 (when all input document pa ge s weigh the sa me), or enter the finis hed a ccumula te d we ight of the input documents  (when diffe rent weighte d pa per is us ed within the input feede r).This field mus t be a decima l number with one digit to the left of the de cima l point, and three digits to the right (e.g., 1.020). IMPORTANT NOTE: Whe n diffe rent weighted input documents  are not us ed, the a mount of pos ta ge a pplied is ba s ed on the weight tha t tha t is s pecifie d in the input fe ede r setup s creen. Ea ch time a pa ge is fed, the we ight for an indivIdua l she et is added to the tota l. If there is a va lue grea ter tha n zero in this field, it too will be a dde d to the tota l weight, and there fore the mete r will add pos ta ge ba s e d on a we ight tha t is he a vie r tha n the ma ilpie ce a ctua lly is . IMPORTANT NOTE: Whe n diffe rent weighted input documents  are us ed, enter the tota l weight for the input pa ge s in this field, and specify 0.000 for the weight within the input fee der setup scree n so tha t a dditiona l we ight is not added to the tota l accumula ted weight.', N'For us always 0.000', N'0.000', N'varchar(255)', N'{0,-<len>}', N'0.000')
GO
